import{_ as e,c as r,o as a,V as t}from"./chunks/framework.e2d10ea7.js";const f=JSON.parse('{"title":"组件库简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),l={name:"guide/index.md"},i=t('<h1 id="组件库简介" tabindex="-1">组件库简介 <a class="header-anchor" href="#组件库简介" aria-label="Permalink to &quot;组件库简介&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><ul><li><p>本框架组件库主要是基于 vue3.0 + vite3.0 版本以上 + vue-router + pinia + element-plus + vxe-table + icon-park(字节跳动——图标) + echarts + vue-i18n 等封装的使用于管理平台风格的基础框架， 框架可用简单的配置完成页面的开发以及交互</p></li><li><p>这里对 vue、element-plus 做的是自动导入 + 按需加载;</p></li><li><p>对 echarts、vxe-table 也是做了特殊处理（按需加载）—— 仅仅引入了组件中使用到的模块 【若想支持更多， 需要自己在项目中重新全局导入即可】</p></li></ul><h2 id="使用到的基础技术库的相关地址" tabindex="-1">使用到的基础技术库的相关地址 <a class="header-anchor" href="#使用到的基础技术库的相关地址" aria-label="Permalink to &quot;使用到的基础技术库的相关地址&quot;">​</a></h2><ul><li><a href="https://cn.vuejs.org/api/" target="_blank" rel="noreferrer">vue 官网</a></li><li><a href="https://vitejs.cn/guide/" target="_blank" rel="noreferrer">vite 官网</a></li><li><a href="https://router.vuejs.org/zh/" target="_blank" rel="noreferrer">vue-router 官网</a></li><li><a href="https://pinia.vuejs.org/zh/" target="_blank" rel="noreferrer">pinia 官网</a></li><li><a href="https://vitejs.cn/guide/" target="_blank" rel="noreferrer">element-plus 官网</a></li><li><a href="https://vxetable.cn/v3/#/table/start/install" target="_blank" rel="noreferrer">vxe-table 官网</a></li><li><a href="http://iconpark.oceanengine.com/home" target="_blank" rel="noreferrer">字节跳动图标官网</a></li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">echarts 官网</a></li><li><a href="https://kazupon.github.io/vue-i18n/zh/guide/messages.html" target="_blank" rel="noreferrer">vue-i18n 官网</a></li></ul>',5),n=[i];function o(h,s,u,c,p,_){return a(),r("div",null,n)}const g=e(l,[["render",o]])